package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string
var WsTax decimal.Decimal
var WsNet decimal.Decimal
var WsTotalTax decimal.Decimal
var WsCount int64
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxRec TaxRec
var inputDone bool

var fileReader *bufio.Scanner
var fileHandle *os.File

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func pow10Decimal(n int) decimal.Decimal {
	return decimal.NewFromInt(pow10(n))
}

// store simulates MOVE / COMPUTE store into PIC 9(intDigits)V99
func storeDecimal(v decimal.Decimal, intDigits int, fracDigits int, rounded bool) decimal.Decimal {
	var scaled decimal.Decimal
	if rounded {
		v = v.Round(int32(fracDigits))
	} else {
		v = v.Truncate(int32(fracDigits))
	}
	// overflow: keep low-order digits that fit
	// total digits = intDigits + fracDigits in base 10
	// compute modulus = 10^(intDigits+fracDigits)
	// work in scaled integer domain to avoid floating errors
	shifted := v.Shift(int32(fracDigits)) // v * 10^frac
	// truncation already done, but ensure integer part truncated toward zero
	shifted = shifted.Truncate(0)
	// handle sign separately, COBOL keeps sign but PIC 9 is unsigned; we just modulo absolute and reapply sign
	sign := shifted.Sign()
	absShifted := shifted.Abs()
	mod := decimal.NewFromInt(1).Shift(int32(intDigits + fracDigits)) // 10^(intDigits+fracDigits)
	if absShifted.Cmp(mod) >= 0 {
		absShifted = absShifted.Mod(mod)
	}
	if sign < 0 {
		absShifted = absShifted.Neg()
	}
	result := absShifted.Shift(int32(-fracDigits))
	// ensure scale exactly fracDigits
	result = result.Truncate(int32(fracDigits))
	return result
}

func formatEdited(val decimal.Decimal, picture string) string {
	// split picture at '.'
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	var fracDigits int
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
		fracDigits = len(fracPic)
	} else {
		intPic = picture
		fracPic = ""
		fracDigits = 0
	}
	// count digit placeholders in intPic
	intDigitsNeeded := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigitsNeeded++
		}
	}
	absVal := val.Abs()
	// get scaled integer: absVal * 10^fracDigits truncated
	shifted := absVal.Shift(int32(fracDigits)).Truncate(0)
	// shifted is integer representing intPart*10^frac + fracPart
	// extract intPart and fracPart
	tenFrac := pow10(fracDigits)
	if tenFrac == 0 {
		tenFrac = 1
	}
	intPart := int64(0)
	fracPart := int64(0)
	if fracDigits > 0 {
		// use decimal to avoid int64 overflow for large values? intDigits max 8 +2 =10 digits fits int64
		ipDec := shifted.Div(decimal.NewFromInt(tenFrac)).Truncate(0)
		fpDec := shifted.Mod(decimal.NewFromInt(tenFrac))
		intPart = ipDec.IntPart()
		fracPart = fpDec.IntPart()
		if fracPart < 0 {
			fracPart = -fracPart
		}
	} else {
		intPart = shifted.IntPart()
		if intPart < 0 {
			intPart = -intPart
		}
	}
	// overflow: drop high-order digits
	if intDigitsNeeded > 0 {
		mod := pow10(intDigitsNeeded)
		intPart = intPart % mod
	}
	// build zero-padded digit string for int part
	intDigitsStr := fmt.Sprintf("%0*d", intDigitsNeeded, intPart)

	// map digits to intPic placeholders
	// Build result for intPic part
	intResult := make([]rune, len(intPic))
	digitIdx := 0
	// iterate over intPic chars, fill digit placeholders from intDigitsStr
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intResult[i] = rune(intDigitsStr[digitIdx])
			digitIdx++
		} else {
			intResult[i] = ch // comma
		}
	}
	// suppression for Z
	// Find index of digit placeholders and determine first non-zero
	// Suppression applies left to right: a Z position is suppressed (becomes space) if digit is '0' and no non-zero has been seen yet in any digit placeholder.
	seenNonZero := false
	// First pass to find suppression, but need to know for Z only
	// We'll iterate digit placeholders in order
	digitPos := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := intDigitsStr[digitPos]
			if d != '0' {
				seenNonZero = true
			}
			if ch == 'Z' && !seenNonZero {
				// check if there is any non-zero later? No, suppression is based on prefix only?
				// Actually if later digit is non-zero, current zero should still be suppressed (leading zero)
				// So we suppress when all digits up to and including? No, COBOL suppresses leading zeros: a Z is space if the digit is zero and no non-zero to its left has been encountered and no non-zero digit exists in more significant positions.
				// But also if later digits have non-zero, current zero remains suppressed.
				// Our seenNonZero currently includes current digit, so need to check before including current?
				// Correct logic: a Z placeholder containing '0' is suppressed if every digit placeholder at or before? Actually no.
				// Simpler: find position of first non-zero digit among digit placeholders (leftmost). All Z placeholders before that digit become spaces, even if they are '0'.
				// If all zeros, all Z become spaces.
			}
			digitPos++
		}
		_ = i
	}
	// Find firstNonZero index among digit placeholders
	firstNonZero := -1
	for idx, ch := range intDigitsStr {
		if ch != '0' {
			firstNonZero = idx
			break
		}
	}
	// Now apply suppression
	digitPos = 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			if ch == 'Z' {
				if firstNonZero == -1 {
					// all zeros -> suppress all Z
					intResult[i] = ' '
				} else if digitPos < firstNonZero {
					intResult[i] = ' '
				} else {
					// keep digit (intResult already digit)
				}
			}
			digitPos++
		}
	}
	// commas become spaces if all digit placeholders to left are suppressed (i.e., are spaces)
	// Determine for each comma whether to keep
	for i, ch := range intPic {
		if ch == ',' {
			// check if any non-suppressed digit placeholder exists to left
			hasVisibleLeft := false
			for j := 0; j < i; j++ {
				if intPic[j] == 'Z' || intPic[j] == '9' {
					if intResult[j] != ' ' {
						hasVisibleLeft = true
						break
					}
				}
			}
			// also check if there is any visible digit to right? COBOL keeps comma only if there is a digit to left? Spec says commas inside suppressed zone become spaces.
			if !hasVisibleLeft {
				intResult[i] = ' '
			} else {
				// also comma should become space if all remaining digits to right are suppressed? But in typical COBOL, comma after suppressed zone stays if there is visible digit somewhere left, even if right side still has digits. Our rule above already handles.
			}
		}
	}

	// Build final string
	var sb strings.Builder
	sb.WriteString(string(intResult))
	if dotIdx >= 0 {
		sb.WriteString(".")
		fracStr := fmt.Sprintf("%0*d", fracDigits, fracPart)
		// frac picture is all 9s, always digits
		sb.WriteString(fracStr)
	}
	result := sb.String()
	// Ensure length equals picture length (pad already)
	return result
}

func formatCount(cnt int64) string {
	// PIC 9(3) zero-padded to 3
	// overflow: low-order 3 digits
	cnt = cnt % 1000
	if cnt < 0 {
		cnt += 1000
	}
	return fmt.Sprintf("%03d", cnt)
}

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty -> EOF immediately
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	fileHandle = f
	fileReader = bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	fileReader.Buffer(buf, 10*1024*1024)
	WsEofFlag = "N"
	inputDone = false
}

func closeInput() {
	if fileHandle != nil {
		fileHandle.Close()
	}
}

func readPara() {
	if inputDone {
		return
	}
	if fileReader == nil {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	if !fileReader.Scan() {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	line := fileReader.Text()
	// COBOL LINE SEQUENTIAL: pad with spaces on right if shorter than record length 13
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	}
	if len(line) > 13 {
		line = line[:13]
	}
	// parse
	trId := line[0:5]
	trIncomeRaw := line[5:13]
	// parse TR-INCOME PIC 9(6)V99 digits only
	trimmed := strings.TrimSpace(trIncomeRaw)
	if trimmed == "" {
		trimmed = "0"
	}
	// Remove any non-digit? Assume digits
	// Parse as integer
	var n int64
	// trimmed should be 8 digits, but may contain spaces already removed
	// If trimmed contains non-digit, fallback to 0
	isDigits := true
	for _, c := range trimmed {
		if c < '0' || c > '9' {
			isDigits = false
			break
		}
	}
	if isDigits {
		fmt.Sscanf(trimmed, "%d", &n)
	} else {
		n = 0
	}
	dec := decimal.New(n, -2)
	taxRec.TrId = trId
	taxRec.TrIncome = dec
	WsEofFlag = "N"
	inputDone = false
}

func processPara() {
	trIncome := taxRec.TrIncome
	// IF TR-INCOME <= 10000.00
	limit1 := decimal.NewFromInt(10000).Shift(0) // 10000
	limit1 = limit1.Add(decimal.NewFromInt(0))   // ensure scale not needed
	// Use decimal comparison
	tenThousand := decimal.New(1000000, -2) // 10000.00
	fortyThousand := decimal.New(4000000, -2)
	oneThousand := decimal.New(100000, -2)
	sevenThousand := decimal.New(700000, -2)
	zeroPointOne := decimal.NewFromFloat(0.10)
	zeroPointTwo := decimal.NewFromFloat(0.20)
	zeroPointThree := decimal.NewFromFloat(0.30)

	_ = limit1
	_ = zeroPointOne
	if trIncome.Cmp(tenThousand) <= 0 {
		calc := trIncome.Mul(decimal.NewFromFloat(0.10))
		WsTax = storeDecimal(calc, 7, 2, true)
	} else {
		if trIncome.Cmp(fortyThousand) <= 0 {
			diff := trIncome.Sub(tenThousand)
			calc := oneThousand.Add(diff.Mul(decimal.NewFromFloat(0.20)))
			WsTax = storeDecimal(calc, 7, 2, true)
		} else {
			diff := trIncome.Sub(fortyThousand)
			calc := sevenThousand.Add(diff.Mul(decimal.NewFromFloat(0.30)))
			WsTax = storeDecimal(calc, 7, 2, true)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX
	netCalc := trIncome.Sub(WsTax)
	WsNet = storeDecimal(netCalc, 7, 2, false)

	// ADD WS-TAX TO WS-TOTAL-TAX
	newTotal := WsTotalTax.Add(WsTax)
	WsTotalTax = storeDecimal(newTotal, 9, 2, false)

	// ADD 1 TO WS-COUNT (PIC 9(3) overflow)
	WsCount = (WsCount + 1) % 1000

	WsIncEd = formatEdited(trIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")

	// DISPLAY TR-ID " " WS-INC-ED " " WS-TAX-ED " " WS-NET-ED
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
}

func mainPara() {
	openInput()
	readPara()
	for !inputDone {
		processPara()
		readPara()
	}
	closeInput()
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	cntStr := formatCount(WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", cntStr, WsTotalEd)
}

func main() {
	// initialize working-storage defaults
	WsEofFlag = "N"
	WsTax = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalTax = decimal.NewFromInt(0)
	WsCount = 0
	mainPara()
}

